function geometry(three, surface, inverse){
  const [vertexCount, encoded] = surface;
  const binary = atob(encoded);
  const bytes = Uint8Array.from(binary, character => character.charCodeAt(0));
  const data = new DataView(bytes.buffer);
  const positions = new Float32Array(vertexCount * 3);
  for(let i=0; i<positions.length; i++) positions[i] = data.getInt16(i * 2, true) / 16000;
  const indexOffset = positions.length * 2;
  const indices = new Uint16Array((bytes.length - indexOffset) / 2);
  for(let i=0; i<indices.length; i++) indices[i] = data.getUint16(indexOffset + i * 2, true);
  const shape = new three.BufferGeometry();
  shape.setAttribute('position', new three.BufferAttribute(positions, 3));
  shape.setIndex(new three.BufferAttribute(indices, 1));
  shape.applyMatrix4(inverse);
  shape.computeVertexNormals();
  return shape;
}
// The source assembly uses one common frame. Store each surface in the
// existing mover's local frame, preserving its vertebral pivot and material.
window.azAttachThorax = function(three, ribs, sternum){
  sternum.updateMatrix();
  const attachments = [];
  function fit(target, frame, key, name){
    frame.updateMatrix();
    const fitted = geometry(three, surfaces[key], frame.matrix.clone().invert());
    target.geometry.dispose();
    target.geometry = fitted;
    target.name = name;
    if(costalWeights[key]){
      const [start, encoded] = costalWeights[key];
      const meshPositions = fitted.attributes.position;
      target.userData.azRestPositions = meshPositions.array.slice();
      target.userData.azRestNormals = fitted.attributes.normal.array.slice();
      attachments.push({
        frame, mesh:target, start,
        weight:Uint8Array.from(atob(encoded), character => character.charCodeAt(0)),
        restToSternum:sternum.matrix.clone().invert().multiply(frame.matrix)
      });
    }
  }
  ribs.forEach((group, i) => {
    const side = i % 2 === 0 ? 'Right' : 'Left';
    const level = Math.floor(i / 2) + 1;
    fit(group.children[0], group, side[0] + level, 'BodyParts3D ' + side.toLowerCase() + ' rib ' + level);
  });
  fit(sternum, sternum, 'sternum', 'BodyParts3D sternum');
  const transform = new three.Matrix4(), point = new three.Vector3(), goal = new three.Vector3();
  // The bony ends follow their individual rib, while the medial cartilage
  // attachments follow the sternum. Weights reflect distance to both joints.
  return function fitCostalCartilage(){
    sternum.updateMatrix();
    for(const {frame, mesh, start, weight, restToSternum} of attachments){
      frame.updateMatrix();
      transform.copy(frame.matrix).invert().multiply(sternum.matrix).multiply(restToSternum);
      const position = mesh.geometry.attributes.position, rest = mesh.userData.azRestPositions;
      for(let i=0; i<weight.length; i++){
        if(!weight[i]) continue;
        const index = start + i;
        goal.fromArray(rest, index * 3).applyMatrix4(transform);
        point.fromBufferAttribute(position, index).lerp(goal, weight[i] / 255);
        position.setXYZ(index, point.x, point.y, point.z);
      }
      position.needsUpdate = true;
      mesh.geometry.computeVertexNormals();
    }
  };
};
